//! Cargo-driven `libjpeg.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x733a0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fefe000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fefe000000u64)),
        o => panic!("libjpeg-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["import:msvcrt", "import:kernel32", "body", "import:ntdll", "engine:oldnames"],
        "x86_64" => &["import:msvcrt", "import:kernel32", "body", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["import:msvcrt", "import:kernel32", "body", "import:ntdll", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("libjpeg_shims", &["vendor/libjpeg/jaricom.c", "vendor/libjpeg/jcapimin.c", "vendor/libjpeg/jcapistd.c", "vendor/libjpeg/jcarith.c", "vendor/libjpeg/jccoefct.c", "vendor/libjpeg/jccolor.c", "vendor/libjpeg/jcdctmgr.c", "vendor/libjpeg/jchuff.c", "vendor/libjpeg/jcinit.c", "vendor/libjpeg/jcmainct.c", "vendor/libjpeg/jcmarker.c", "vendor/libjpeg/jcmaster.c", "vendor/libjpeg/jcomapi.c", "vendor/libjpeg/jcparam.c", "vendor/libjpeg/jcprepct.c", "vendor/libjpeg/jcsample.c", "vendor/libjpeg/jctrans.c", "vendor/libjpeg/jdapimin.c", "vendor/libjpeg/jdapistd.c", "vendor/libjpeg/jdarith.c", "vendor/libjpeg/jdatadst.c", "vendor/libjpeg/jdatasrc.c", "vendor/libjpeg/jdcoefct.c", "vendor/libjpeg/jdcolor.c", "vendor/libjpeg/jddctmgr.c", "vendor/libjpeg/jdhuff.c", "vendor/libjpeg/jdinput.c", "vendor/libjpeg/jdmainct.c", "vendor/libjpeg/jdmarker.c", "vendor/libjpeg/jdmaster.c", "vendor/libjpeg/jdmerge.c", "vendor/libjpeg/jdpostct.c", "vendor/libjpeg/jdsample.c", "vendor/libjpeg/jdtrans.c", "vendor/libjpeg/jerror.c", "vendor/libjpeg/jfdctflt.c", "vendor/libjpeg/jfdctfst.c", "vendor/libjpeg/jfdctint.c", "vendor/libjpeg/jidctflt.c", "vendor/libjpeg/jidctfst.c", "vendor/libjpeg/jidctint.c", "vendor/libjpeg/jquant1.c", "vendor/libjpeg/jquant2.c", "vendor/libjpeg/jutils.c", "vendor/libjpeg/jmemmgr.c", "vendor/libjpeg/jmemnobs.c"])
        .whole_c_objects("libjpeg_shims")
        .spec2def("vendor/libjpeg/libjpeg.spec", "libjpeg.dll")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
